(function() {
  'use strict';
  // Subtle breathing animation synced to system time for ambient rhythm
  const root = document.documentElement;
  function updateBeat() {
    const seconds = new Date().getSeconds();
    const beat = 0.6 + Math.abs(Math.sin(seconds / 60 * Math.PI * 2)) * 0.4;
    root.style.setProperty('--pulse-scale', beat.toFixed(3));
  }
  setInterval(updateBeat, 1000);
  updateBeat();
})();

