:root {
  /* Aurora Pulse Theme - luminous ribbons that breathe with time */
  --bg-primary: #05070f;
  --bg-alt: #0a1020;
  --bg-hover: rgba(114, 224, 255, 0.08);
  --text-primary: #e9f4ff;
  --text-secondary: #a8d1ff;
  --accent: #78ffb0;
  --accent-2: #74c0ff;
  --accent-3: #c57bff;
  --border: rgba(120, 255, 176, 0.35);
}

body {
  background: radial-gradient(circle at 12% 20%, rgba(116, 192, 255, 0.22), transparent 30%),
              radial-gradient(circle at 82% 70%, rgba(197, 123, 255, 0.16), transparent 35%),
              linear-gradient(140deg, #05070f 0%, #0a1020 60%, #04060c 100%);
  color: var(--text-primary);
}

.card {
  background: linear-gradient(135deg, rgba(120, 255, 176, 0.12), rgba(116, 192, 255, 0.12)), rgba(255, 255, 255, 0.02);
  border: 1px solid var(--border);
  box-shadow: 0 24px 50px rgba(0, 0, 0, 0.45), 0 0 1px rgba(116, 192, 255, 0.4);
  position: relative;
  overflow: hidden;
  transform: translateZ(0);
}

.card::before, .card::after {
  content: '';
  position: absolute;
  inset: -40%;
  background: conic-gradient(from 80deg, rgba(120, 255, 176, 0.1), rgba(197, 123, 255, 0.06), rgba(116, 192, 255, 0.08), rgba(120, 255, 176, 0.1));
  animation: auroraSweep 18s linear infinite;
  filter: blur(50px) saturate(140%);
  pointer-events: none;
}

.card::after {
  animation-duration: 26s;
  animation-direction: reverse;
  opacity: 0.7;
}

.card:hover {
  box-shadow: 0 30px 60px rgba(116, 192, 255, 0.35), 0 0 1px rgba(120, 255, 176, 0.55);
  border-color: rgba(120, 255, 176, 0.6);
}

.card-title {
  text-transform: uppercase;
  letter-spacing: 1px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2), var(--accent-3));
  -webkit-background-clip: text;
  color: transparent;
}

.card:hover .card-title {
  filter: drop-shadow(0 0 10px rgba(116, 192, 255, 0.4));
}

.button {
  background: linear-gradient(120deg, rgba(120, 255, 176, 0.2), rgba(116, 192, 255, 0.2));
  border: 1px solid var(--border);
  color: var(--text-primary);
  transition: transform 0.2s ease, border-color 0.2s;
}

.button:hover {
  transform: scale(calc(1 + (var(--pulse-scale, 1) - 0.9) * 0.05));
  border-color: rgba(116, 192, 255, 0.6);
}

@keyframes auroraSweep {
  0% { transform: translateX(-10%) rotate(0deg); opacity: 0.45; }
  50% { transform: translateX(6%) rotate(180deg); opacity: 0.7; }
  100% { transform: translateX(-10%) rotate(360deg); opacity: 0.45; }
}
